package net.civeira.phylax.feature.observe.observedissuecomment.domain.gateway;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

class ObservedIssueCommentCursorUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_observed_issue_comment_cursor_builder() {
    ObservedIssueCommentCursor cursor = ObservedIssueCommentCursor.builder().build();
    Assertions.assertFalse(cursor.getLimit().isPresent(),
        "Limit must be empty if cursor is build without it");
    Assertions.assertFalse(cursor.getSinceUid().isPresent(),
        "Since must be empty if cursor is build without it");
    cursor.setLimit(100);
    Assertions.assertEquals(100, cursor.getLimit().get(), "Limit must be the same as the assigned");
    cursor.setSinceUid("one");
    Assertions.assertEquals("one", cursor.getSinceUid().get(),
        "Since Uid must be the same as the assigned");
    Assertions.assertTrue(cursor.getOrder().isEmpty(), "The order must be empty");
    cursor.setOrder(List.of(ObservedIssueCommentOrder.AUTHOR_NAME_ASC,
        ObservedIssueCommentOrder.AUTHOR_NAME_DESC));
    Assertions.assertEquals(
        List.of(ObservedIssueCommentOrder.AUTHOR_NAME_ASC,
            ObservedIssueCommentOrder.AUTHOR_NAME_DESC),
        cursor.getOrder(), "The order must be the same that was assinged");
    Assertions.assertTrue(cursor.getSinceAuthorName().isEmpty(),
        "The value since for AuthorName must be empty");
    cursor.setSinceAuthorName("one");
    Assertions.assertEquals("one", cursor.getSinceAuthorName().get(),
        "The value since for AuthorName must be the same that was assinged");
  }
}
